 <section class="account-card"><h2>Destek geçmişim</h2><?php foreach(($tickets??[]) as $t): ?><article class="ticket-item"><div class="ticket-top"><strong><?= e($t['subject']) ?></strong><span class="account-status"><?= e($t['status']) ?></span></div><p><?= nl2br(e($t['message'])) ?></p><?php if($t['admin_reply']): ?><div class="ticket-reply"><b>Mağaza yanıtı</b><p><?= nl2br(e($t['admin_reply'])) ?></p></div><?php endif; ?><small><?= e(date('d.m.Y H:i',strtotime($t['created_at']))) ?></small></article><?php endforeach; ?><?php if(empty($tickets)): ?><p class="muted">Henüz destek talebiniz yok.</p><?php endif; ?></section></div>
